        mockMvc.perform(get("/api/releases/" + releaseId + "/monitor")).andExpect(status().isOk());
        mockMvc.perform(get("/api/releases/" + releaseId + "/history"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.pauses.length()").value(0))
