private CertChain requireCurrentChain(String firmwareVersion, String deviceId) {
    List<CertChain> chains = certChainRepository.findByFirmwareVersion(firmwareVersion);
    if (chains.isEmpty()) return null;
    Instant now = Instant.now(clock);
    // 覆盖当前时刻的链
    var covering = chains.stream().filter(c -> c.covers(now)).findFirst();
    if (covering.isPresent()) {
        CertChain c = covering.get();
        if (c.revokedAtUtc() != null) throw 422 CERT_CHAIN_REVOKED;
        if (deviceId != null && !deviceTrustRepository.exists(deviceId, c.id())) throw 422 DEVICE_NOT_TRUSTED;
        return c;
    }
    boolean anyFuture = chains.stream().anyMatch(c -> Instant.parse(c.validFromUtc()).isAfter(now));
    if (anyFuture) throw 422 CERT_CHAIN_NOT_YET_EFFECTIVE;
    throw 422 CERT_CHAIN_EXPIRED;
}
